"""The dbscheme text: a node type and its tables per dataclass, a type per union, and the hand-written facts before them."""

from functools import singledispatch

from cobble.experimental.codeql.schema.schema import (
    NodeField,
    NodeType,
    Schema,
    UnionType,
)
from cobble.experimental.codeql.schema.shape import (
    Absent,
    Keyed,
    Located,
    NodeRef,
    Repeated,
    Scalar,
    Shape,
)

AST_NODE = "cobol_ast_node"
LOCATION = "location_default"
LOCATIONS = "locations_default"

HEADER = (
    "/* Generated by cobble-experimental-codeql-schema from the parser's types: "
    "do not edit. */\n"
)


_RESERVED = frozenset(
    {
        "boolean",
        "case",
        "date",
        "float",
        "int",
        "key",
        "of",
        "ref",
        "string",
        "unique",
        "varchar",
    }
)


def _name(name: str) -> str:
    """A field's column name; a dbscheme keyword gets a trailing underscore."""
    return f"{name}_" if name in _RESERVED else name


def column(field: str, shape: Shape) -> str:
    stored, typed = _column_types(shape)
    return f"{stored} {_name(field)}: {typed} ref"


@singledispatch
def _column_types(shape: Shape) -> tuple[str, str]:
    """What a column of this shape stores, and the type it is declared with."""
    raise TypeError(f"{shape} is not a column")


@_column_types.register
def _(shape: Scalar) -> tuple[str, str]:
    return shape.kind.value, shape.kind.value


@_column_types.register
def _(shape: NodeRef) -> tuple[str, str]:
    return "int", f"@{shape.name}"


@_column_types.register
def _(shape: Located) -> tuple[str, str]:
    return "int", f"@{LOCATION}"


def is_column(shape: Shape) -> bool:
    return isinstance(shape, (Scalar, NodeRef, Located))


def child_table(node: NodeType, field: NodeField) -> str:
    return f"{node.table}_{field.name}"


def _table(name: str, columns: tuple[str, ...]) -> str:
    return f"{name}(\n" + ",\n".join(f"  {c}" for c in columns) + "\n);\n"


def _owner(node: NodeType) -> str:
    return f"int id: @{node.table} ref"


def _definition(node: NodeType) -> str:
    own = tuple(column(f.name, f.shape) for f in node.fields if is_column(f.shape))
    return _table(f"{node.table}_def", (f"unique int id: @{node.table}", *own))


def _field_tables(node: NodeType, field: NodeField) -> tuple[str, ...]:
    return _tables_of(field.shape, node, child_table(node, field))


@singledispatch
def _tables_of(shape: Shape, node: NodeType, name: str) -> tuple[str, ...]:
    """A column on the owner's row needs no table of its own."""
    return ()


@_tables_of.register
def _(shape: Absent, node: NodeType, name: str) -> tuple[str, ...]:
    return (_table(name, (f"unique {_owner(node)}", column("value", shape.inner))),)


@_tables_of.register
def _(shape: Repeated, node: NodeType, name: str) -> tuple[str, ...]:
    columns = (_owner(node), "int index: int ref", column("value", shape.element))
    return (_table(name, columns),)


@_tables_of.register
def _(shape: Keyed, node: NodeType, name: str) -> tuple[str, ...]:
    return _keyed_tables(node, name, shape.value)


def _keyed_tables(node: NodeType, name: str, value: Shape) -> tuple[str, ...]:
    """A key row per entry, and a value row per entry that holds one."""
    keys = (_owner(node), "int index: int ref", "string entry_key: string ref")
    values = (_owner(node), "int index: int ref", column("value", present(value)))
    return (_table(name, keys), _table(f"{name}_value", values))


def present(shape: Shape) -> Shape:
    """What an entry holds when it holds anything."""
    return shape.inner if isinstance(shape, Absent) else shape


def _node_tables(node: NodeType) -> str:
    tables = (
        _definition(node),
        *(t for f in node.fields for t in _field_tables(node, f)),
    )
    return "\n".join(tables)


def _union(union: UnionType) -> str:
    return f"@{union.table} = " + " | ".join(f"@{m}" for m in union.members) + ";\n"


def dbscheme_text(schema: Schema, preamble: str) -> str:
    every = UnionType("", AST_NODE, tuple(n.table for n in schema.nodes))
    return "\n".join(
        (
            HEADER,
            preamble,
            *(_node_tables(n) for n in schema.nodes),
            *(_union(u) for u in schema.unions),
            _union(every),
        )
    )
